  "gram-91": {"promptNative": "Il libro è _____ tavolo. (su una superficie)", "explain": "'на' + prepositivo per una superficie (sopra): на столе. ('в' = dentro; 'под' + strumentale = sotto.)", "wrongNote": "'на' + prepositivo per una superficie → на столе."},
